using Captovix;
int n=0;void Check(bool v,string message){if(!v)throw new Exception(message);n++;Console.WriteLine("PASS: "+message);}bool Near(double a,double b)=>Math.Abs(a-b)<1e-5;
AnnotationBox Local(Annotation a)=>new(a.Left,a.Top,a.Width,a.Height);AnnotationBox Bounds(Annotation a)=>ObjectControl.RotatedBounds(Local(a),a.Rotation);
Annotation Shape(double x,double y,double w,double h)=>new(){Kind=AnnotationKind.Rectangle,X1=x,Y1=y,X2=x+w,Y2=y+h};
EditorDocument Doc(ImageAppearance? appearance=null)=>new(){OriginalWidth=400,OriginalHeight=300,Appearance=appearance??new()};
for(int turn=0;turn<4;turn++)foreach(bool flip in new[]{false,true}){
 var style=CanvasEditing.Expand(new(0,0,400,300),new(){QuarterTurns=turn,FlipHorizontal=flip},30,40,50,60);style.ResizeWidth=turn%2==0?800:600;style.ResizeHeight=turn%2==0?450:600;
 var doc=Doc(style);doc.Annotations=[Shape(50,60,80,50)];var id=doc.Annotations[0].Id;var before=new ImageLayout(doc.Viewport,doc.Appearance);int width=before.Width,height=before.Height;var original=doc.Serialize();
 var frame=ObjectPrecision.Frame(doc,[id],Bounds);ObjectPrecision.ApplyFrame(doc,[id],37,43,frame.Width*1.5,frame.Height*.75,0,Bounds,Local);var after=ObjectPrecision.Frame(doc,[id],Bounds);
 Check(Near(after.X,37)&&Near(after.Y,43)&&Near(after.Width,frame.Width*1.5)&&Near(after.Height,frame.Height*.75),"Numeric output frame respects quarter-turn/flip/resize "+turn+"/"+flip);
 Check(new ImageLayout(doc.Viewport,doc.Appearance).Width==width&&new ImageLayout(doc.Viewport,doc.Appearance).Height==height&&doc.OriginalWidth==400&&doc.OriginalHeight==300,"Editing objects never changes image or output extent");
 ObjectPrecision.Align(doc,[id],AnnotationAlignment.CenterX,AlignmentReference.Canvas,Bounds);after=ObjectPrecision.Frame(doc,[id],Bounds);Check(Near(after.CenterX,width/2d),"Single shape centers on output canvas");
 ObjectPrecision.Align(doc,[id],AnnotationAlignment.Left,AlignmentReference.Image,Bounds);after=ObjectPrecision.Frame(doc,[id],Bounds);Check(Near(after.X,ObjectPrecision.VisibleImage(doc)!.Value.X),"Shape aligns to visible image extent");
 var session=new EditorSession(EditorDocument.Deserialize(original));session.Change(d=>ObjectPrecision.ApplyFrame(d,[id],15,25,frame.Width,frame.Height,0,Bounds,Local));session.Undo();Check(session.Document.Serialize()==original,"One numeric Undo restores geometry and appearance bytes");session.Redo();Check(Near(ObjectPrecision.Frame(session.Document,[id],Bounds).X,15),"Redo restores output position");
}
foreach(int turn in new[]{0,1,2,3}){
 var doc=Doc(new(){QuarterTurns=turn,FlipVertical=true});var a=Shape(20,30,30,20);var b=Shape(100,70,40,25);var c=Shape(250,180,50,30);doc.Annotations=[a,b,c];var ids=doc.Annotations.Select(a=>a.Id).ToArray();
 var l=new ImageLayout(doc.Viewport,doc.Appearance);var before=doc.Annotations.Select(a=>ObjectPrecision.Map(Bounds(a),l)).OrderBy(b=>b.X).ToArray();
 Check(ObjectPrecision.Distribute(doc,ids,true,Bounds),"Distribute accepts three shapes after transform");var boxes=doc.Annotations.Select(a=>ObjectPrecision.Map(Bounds(a),l)).OrderBy(b=>b.X).ToArray();Check(Near(boxes[1].X-boxes[0].Right,boxes[2].X-boxes[1].Right)&&Near(boxes[0].X,before[0].X)&&Near(boxes[^1].Right,before[^1].Right),"Equal gaps use output widths, keeping first/last fixed");
 ObjectPrecision.Align(doc,ids,AnnotationAlignment.Top,AlignmentReference.Selection,Bounds);boxes=doc.Annotations.Select(a=>ObjectPrecision.Map(Bounds(a),l)).ToArray();Check(boxes.All(b=>Near(b.Y,boxes[0].Y)),"Multi-selection aligns to union");
}
var grouped=Doc();var g1=Shape(20,30,40,30);var g2=Shape(90,80,20,30);grouped.Annotations=[g1,g2];string[] groupIds=[g1.Id,g2.Id];AnnotationEditing.Group(grouped,groupIds);var oldDistance=g2.X1-g1.X1;var oldFrame=ObjectPrecision.Frame(grouped,groupIds,Bounds);ObjectPrecision.ApplyFrame(grouped,[g1.Id],50,60,oldFrame.Width*2,oldFrame.Height*2,0,Bounds,Local);Check(Near(g2.X1-g1.X1,oldDistance*2)&&g1.GroupId==g2.GroupId,"Numeric resize expands all group members with preserved relationship");ObjectControl.Lock(grouped,[g1.Id],true);Check(g1.Locked&&g2.Locked&&!ObjectControl.CanEdit(grouped,groupIds),"Lock from one member locks entire group");
var rotated=Doc();var shape=Shape(70,80,100,60);shape.Rotation=35;rotated.Annotations=[shape];var rb=ObjectPrecision.Frame(rotated,[shape.Id],Bounds);var sessionRotated=new EditorSession(rotated);bool rejected=false;try{sessionRotated.Change(d=>ObjectPrecision.ApplyFrame(d,[shape.Id],20,40,rb.Width*2,rb.Height,35,Bounds,Local));}catch(ArgumentException){rejected=true;}Check(!rejected&&sessionRotated.Dirty,"Nonuniform resize of rotated object is permitted");rotated=Doc();shape=Shape(70,80,100,60);shape.Rotation=35;rotated.Annotations=[shape];ObjectPrecision.ApplyFrame(rotated,[shape.Id],25,35,rb.Width*2,rb.Height*2,35,Bounds,Local);var rotatedAfter=ObjectPrecision.Frame(rotated,[shape.Id],Bounds);Check(Near(rotatedAfter.X,25)&&Near(rotatedAfter.Y,35)&&Near(rotatedAfter.Width,rb.Width*2),"Uniform rotated numeric resize is exact");
for(int handle=0;handle<8;handle++){var box=new AnnotationBox(10,20,80,40);var next=AnnotationEditing.Resize(box,handle,handle is 0 or 6 or 7?-30:150,handle is 0 or 1 or 2?-10:100,true);Check(Near(next.Width/next.Height,2),"Every corner/edge handle preserves ratio "+handle);if(handle is 1 or 5)Check(Near(next.CenterX,box.CenterX),"Vertical edge resize preserves opposite center");if(handle is 3 or 7)Check(Near(next.CenterY,box.CenterY),"Horizontal edge resize preserves opposite center");}
var off=Doc(CanvasEditing.Expand(new(0,0,400,300),new()));var outside=Shape(-90,-80,30,20);off.Annotations=[outside];ObjectPrecision.ApplyFrame(off,[outside.Id],20,30,30,20,0,Bounds,Local);Check(outside.X1<0&&outside.Y1<0,"Numeric canvas coordinates support outside-image annotation");var beforeCopy=outside.X1;var copies=AnnotationEditing.Duplicate(off,[outside.Id],Bounds,CanvasEditing.SourceBounds(off.Viewport,off.Appearance));Check(off.Annotations.Single(a=>copies.Contains(a.Id)).X1<0,"Duplicate outside image stays in expanded canvas");var packet=AnnotationClipboard.Copy(off,[outside.Id]);var pasted=AnnotationClipboard.Paste(off,packet,16,Bounds,CanvasEditing.SourceBounds(off.Viewport,off.Appearance));Check(off.Annotations.Single(a=>pasted.Contains(a.Id)).X1<0,"Paste outside image stays in expanded canvas");
var overlap=Doc();overlap.Annotations=[Shape(0,0,100,10),Shape(20,0,100,10),Shape(40,0,100,10)];string untouched=overlap.Serialize();Check(!ObjectPrecision.Distribute(overlap,overlap.Annotations.Select(a=>a.Id),true,Bounds)&&overlap.Serialize()==untouched,"Insufficient spacing is reported without moving any object");
var snap=ObjectControl.Snap(new(0,20,10,10),new(0,0,200,200),[new(50,0,30,100)],39,1,2,false,true);Check(Near(snap.X,40)&&snap.GuideX==50,"Nearest edge snaps to reference");var free=ObjectControl.Snap(new(0,20,10,10),new(0,0,200,200),[new(50,0,30,100)],39,1,2,false,false);Check(Near(free.X,39)&&free.GuideX==null,"Ctrl-style bypass keeps free position and removes guide");
var hidden=Doc(new(){OutputCrop=new(0,0,20,20)});Check(ObjectPrecision.VisibleImage(hidden)?.Width==20,"Visible image target respects output crop");
var tinyText=new Annotation{Kind=AnnotationKind.Text,FontSize=16,X1=0,Y1=0,X2=50,Y2=20};var limited=ObjectPrecision.LimitResize([tinyText],new(0,0,100,50),new(0,0,10,5),4,true);Check(Near(limited.Width,50)&&Near(limited.Height,25),"Group shrink stops at minimum text size without shifting members");
var giant=ObjectPrecision.LimitResize([tinyText],new(10,20,100,50),new(-1000,-1000,10000,5000),0,true);Check(Near(giant.Width,1500)&&Near(giant.Right,110)&&Near(giant.Bottom,70),"Group enlargement respects max font and opposite corner");
var smallCallout=new Annotation{Kind=AnnotationKind.Callout,X1=0,Y1=0,X2=72,Y2=72};var minimum=ObjectPrecision.LimitResize([smallCallout],new(0,0,72,72),new(0,0,10,15),4,false);Check(Near(minimum.Width,36)&&Near(minimum.Height,36),"Callout resize maintains minimum body on each axis");
var calloutDoc=Doc();calloutDoc.Annotations=[smallCallout];var calloutSession=new EditorSession(calloutDoc);bool minRejected=false;try{calloutSession.Change(d=>ObjectPrecision.ApplyFrame(d,[smallCallout.Id],0,0,10,10,0,Bounds,Local));}catch(ArgumentException){minRejected=true;}Check(minRejected&&!calloutSession.Dirty&&calloutSession.Document.Annotations[0].Width==72,"Too-small numeric callout is rejected atomically");
var lineDoc=Doc();var line=new Annotation{Kind=AnnotationKind.Arrow,X1=20,Y1=30,X2=120,Y2=30};lineDoc.Annotations=[line];ObjectPrecision.ApplyFrame(lineDoc,[line.Id],40,50,200,0,0,Bounds,Local);Check(Near(line.X1,40)&&Near(line.X2,240)&&Near(line.Y1,50)&&Near(line.Y2,50),"Horizontal line can move and resize its nonzero dimension numerically");
var bordered=Doc(new(){CanvasWidth=100,CanvasHeight=80,BorderWidth=10});var visibleBorder=ObjectPrecision.VisibleImage(bordered);Check(visibleBorder?.X==10&&visibleBorder?.Width==100,"Visible image reference excludes border pixels");var borderShape=Shape(160,120,20,20);bordered.Annotations=[borderShape];ObjectPrecision.ApplyFrame(bordered,[borderShape.Id],0,0,8,8,0,Bounds,Local);Check(bordered.Appearance.DrawOutsideImage,"Explicit placement in outer frame enables visible annotation there without resizing canvas");
