foreach(var kind in new[]{AnnotationKind.Callout,AnnotationKind.Rectangle,AnnotationKind.Text,AnnotationKind.Step}){var sample=Shape(10,20,100,80);sample.Kind=kind;Check(!ObjectPrecision.RequiresUniform([sample]),"No forced ratio: "+kind);var source=new AnnotationBox(10,20,100,80);var target=AnnotationEditing.Resize(source,4,110,140,false);var freeResult=ObjectPrecision.LimitResize([sample],source,target,4,false);Check(Near(freeResult.Width,100)&&Near(freeResult.Height,120),"Free vertical side: "+kind);}

foreach(var rotation in new[]{0d,25d,90d}){var original=new Annotation{Kind=AnnotationKind.Callout,CalloutBodyPivot=true,X1=80,Y1=80,X2=280,Y2=200,TailX=40,TailY=100,TextPadding=30,Rotation=rotation};var resized=original.Copy();var old=Local(original);var oldTail=ObjectControl.RotatePoint(new(original.TailX,original.TailY),new(old.CenterX,old.CenterY),rotation);ObjectControl.ResizeSingle(resized,original,old,new(old.X,old.Y,old.Width+90,old.Height),Local);var next=Local(resized);var nextTail=ObjectControl.RotatePoint(new(resized.TailX,resized.TailY),new(next.CenterX,next.CenterY),rotation);Check(Near(nextTail.X,oldTail.X)&&Near(nextTail.Y,oldTail.Y)&&Near(resized.Height,original.Height)&&resized.TextPadding==30,"Width-only resize pins tail and preserves height/padding at rotation"+rotation);}

foreach(bool legacy in new[]{false,true})foreach(var rotation in new[]{0d,35d,90d,-120d}){
 var original=new Annotation{Kind=AnnotationKind.Callout,CalloutBodyPivot=!legacy,X1=100,Y1=120,X2=300,Y2=240,TailX=40,TailY=290,Rotation=rotation,FontSize=28,Text="Tiếng Việt"};
