 var moved=original.Copy();ObjectControl.MoveCalloutBody(moved,original,47,-31,Pivot);var next=Pivot(moved);var tail=ObjectControl.RotatePoint(new(moved.TailX,moved.TailY),new(next.CenterX,next.CenterY),rotation);var center=ObjectControl.RotatePoint(new(moved.Left+moved.Width/2,moved.Top+moved.Height/2),new(next.CenterX,next.CenterY),rotation);
 Check(Near(tail.X,worldTail.X)&&Near(tail.Y,worldTail.Y),"Center grip pins tail at rotation"+rotation+" legacy="+legacy);Check(Near(center.X,worldBody.X+47)&&Near(center.Y,worldBody.Y-31)&&Near(moved.Width,original.Width)&&Near(moved.Height,original.Height)&&moved.Text==original.Text,"Center grip translates body without resizing or changing text");
 var history=Doc();history.Annotations=[original.Copy()];var session=new EditorSession(history);string before=session.Document.Serialize();session.Change(d=>ObjectControl.MoveCalloutBody(d.Annotations[0],original,47,-31,Pivot));string after=session.Document.Serialize();session.Undo();Check(session.Document.Serialize()==before,"Undo restores body, tail and original pivot mode");session.Redo();Check(session.Document.Serialize()==after,"Redo restores body-only movement");
